const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial={destination:'莫干山',origin:'杭州',days:2,budget:1500,pet:true,solo:true,experience:'入门',phase:0,day:1,rerouted:false,pending:false,checks:[{text:'身份证与保险信息',done:true},{text:'防滑徒步鞋',done:true},{text:'防雨外套',done:false},{text:'饮水与便携补给',done:false},{text:'充电宝与头灯',done:false},{text:'宠物牵引绳、饮水碗与拾便袋',done:false},{text:'出发前确认住宿携宠政策',done:false}],expenses:[],memories:[]};
let state;try{state=JSON.parse(localStorage.getItem('wildpath-v1'))||structuredClone(initial);if(!Array.isArray(state.checks)||!Array.isArray(state.expenses))throw Error();}catch{state=structuredClone(initial)}let view='plan',timer;const views={plan:['◈','行程规划','下一站，去自然里。'],packing:['☷','物资清单','准备好，再出发。'],during:['⌁','途中陪伴','路在变，野途在。'],wallet:['▤','旅行账本','每一笔，都有迹可循。'],after:['▧','旅行档案','把路上的片刻留下。']};
function save(){try{localStorage.setItem('wildpath-v1',JSON.stringify(state))}catch{toast('浏览器存储不可用，本次修改仅在当前页面保留')}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
const total=()=>state.expenses.reduce((a,b)=>a+b.amount,0),estimate=()=>Math.round(state.budget*.78)+(state.rerouted?80:0);
function route(day){if(state.fatigued&&day===state.day)return [["现在","暂停活动，原地休息","评估体力，必要时寻求当地工作人员帮助","体力调整"],["稍后","返回住宿","仅在身体状态和交通条件允许时返回","缩短行程"]];if(state.rerouted&&day===1)return [['09:00','住宿内休整','取消户外活动，等待天气好转','雨天替代'],['11:30','就近室内用餐','出行前确认营业与携宠政策','服务待核实'],['14:00','室内手作 / 阅读','仅在交通条件允许时短途出行','节奏放缓'],['18:00','返回住宿','保留原住宿，复核次日天气','住宿不变']];return day===1?[['08:30',`${state.origin}出发`,'交通方式与接驳时间待确认','出发'],['10:30',`${state.destination} · 林间轻徒步`,state.experience==='入门'?'选择开放、标识清楚的短线，及时折返':'选择已开放且适合经验水平的路线','路线示意'],['12:30','山间午餐与补给',state.pet?'预先确认宠物可进入的用餐区域':'用餐、补水，留出休息时间','慢下来'],['15:00','入住山间住宿',state.pet?'向商家确认体型限制、清洁费与牵引要求':'办理入住，整理装备','未预订']]:[['09:00',`第 ${day} 天 · ${day===state.days?'村落漫步':'自然探索'}`,'以开放步道为主，按体力调整距离','轻松节奏'],['12:00','本地午餐','补充饮水，记录沿途片刻','本地体验'],['15:00',day===state.days?`返回${state.origin}`:'回住宿休息',day===state.days?'预留交通缓冲时间':'整理装备并检查次日天气','时间示意']];}
function itinerary(){return `<div class="tabs">${Array.from({length:state.days},(_,i)=>`<button class="${state.day===i+1?'active':''}" data-day="${i+1}">DAY ${String(i+1).padStart(2,'0')}</button>`).join('')}</div>${route(state.day).map(r=>`<div class="stop"><time>${r[0]}</time><i class="point"></i><div><h4>${esc(r[1])}</h4><p>${esc(r[2])}</p><span class="tag">${r[3]}</span></div></div>`).join('')}`}
function budget(){return `<div class="card"><div class="section-heading"><h3>预算有数，出发有底</h3><span class="muted">估算</span></div><div class="big-number">¥${estimate()} <small>/ ¥${state.budget}</small></div>${[['交通',.23],['住宿',.32],['餐饮',.15],['活动与其他',.08]].map(([t,p])=>`<div class="budget-row"><span>${t}</span><span>¥${Math.round(state.budget*p)}</span></div><div class="bar"><i style="width:${p/.32*100}%"></i></div>`).join('')}${state.rerouted?'<div class="budget-row"><span>改线增量</span><span>¥80</span></div>':''}<p class="muted" style="margin-top:18px">预留 ¥${state.budget-estimate()} 弹性空间 · 非实时报价</p></div>`}
function render(){ $('#nav').innerHTML=Object.entries(views).map(([k,v])=>`<button data-view="${k}" class="${view===k?'active':''}">${v[0]}　${v[1]}</button>`).join('');$('#crumb').textContent=views[view][1];$('#page-title').textContent=views[view][2];$('#subtitle').textContent={plan:'把想法交给野途，把时间留给路上。',packing:'为这次行程准备，也为意外留一点余量。',during:'天气、体力、行程变化，都在这里接住。',wallet:'记录实际花费，掌握剩余预算。',after:'行程、笔记和账单，组成属于你的旅行记忆。'}[view];
let html='';if(view==='plan')html=`<div class="grid"><div><div class="hero"><span class="pill">${state.solo?'独行':'结伴'}</span>${state.pet?'<span class="pill">携宠友好优先</span>':''}<span class="pill">${esc(state.experience)}徒步</span><h2>${esc(state.destination)}，向山而行</h2><p>${state.days} 天 ${state.days-1} 夜 · 留一点空白，让沿途发生。</p><div class="hero-bottom"><span>⌁ ${esc(state.origin)}出发</span><span>◷ 轻户外 · 慢节奏</span><span>¥ ${state.budget} 预算</span></div><small class="muted" style="color:#dae4db">户外氛围图 · 非目的地实景</small></div><div class="card"><div class="section-heading"><h3>你的行程，刚刚好</h3><span class="muted">${state.phase?'已开始旅行':'待出发'} · 示例路线</span></div>${itinerary()}<button class="primary" data-action="start">${state.phase?'查看途中陪伴':'确认方案，开始旅行'} ↗</button></div></div><div><div class="card agent"><h3>✧ 野途的规划思路</h3><p>按照「${state.solo?'独行':'结伴'}${state.pet?' + 携宠':''} + ${state.experience}徒步」，优先安排短途活动与充足休息。住宿和路线均需在出发前核实。</p><div class="facts"><div class="fact"><strong>${state.days}</strong><small>旅行天数</small></div><div class="fact"><strong>${state.pet?'1 + 🐾':'1'}</strong><small>演示出行配置</small></div><div class="fact"><strong>轻</strong><small>活动强度</small></div></div><p>下一步：检查物资，确认目的地天气、开放情况与${state.pet?'携宠政策':'交通安排'}。</p><button class="outline" data-view="packing" style="margin-top:14px">查看出发清单 →</button></div>${budget()}</div></div>`;
if(view==='packing'){let n=state.checks.filter(x=>x.done).length;html=`<div class="grid"><div class="card"><div class="section-heading"><h3>出发前 Checklist</h3><span class="muted">${n} / ${state.checks.length} 已准备</span></div><div class="progress"><i style="width:${state.checks.length?n/state.checks.length*100:0}%"></i></div>${state.checks.map((x,i)=>`<div class="check-row ${x.done?'done':''}"><input type="checkbox" aria-label="${esc(x.text)}" data-check="${i}" ${x.done?'checked':''}><label>${esc(x.text)}</label><button class="delete" aria-label="删除${esc(x.text)}" data-delete-check="${i}">×</button></div>`).join('')}<form id="add-item" class="full-form"><input name="item" aria-label="新增物资" placeholder="补充一件你想带的东西" required maxlength="80"><button class="primary">＋ 添加</button></form></div><div class="card agent"><h3>✧ 为这趟旅行准备</h3><p>当前清单基于 ${state.days} 天轻徒步${state.pet?'和携宠出行':''}生成。检查鞋服、补给、电量和天气；专业运动需要另行核实装备、资质与向导。</p><p style="margin-top:16px">清单在当前浏览器自动保存。导出的档案可离线查看，但不包含离线地图。</p></div></div>`}
if(view==='during')html=`<div class="notice">情景模拟：天气与周边服务均未连接实时接口。点击下方按钮演示行程调整。</div><div class="grid"><div><div class="card"><div class="section-heading"><h3>现在的行程</h3><span class="pill" style="color:#43654c;border-color:#cbd8cb">${state.rerouted?'雨天方案':'原定方案'}</span></div>${itinerary()}<div class="action-row"><button class="outline" data-action="rain">☂ 模拟暴雨</button><button class="outline" data-action="tired">模拟疲劳反馈</button><button class="outline" data-action="emergency">应急入口</button></div></div>${state.pending?`<div class="card agent"><h3>户外计划需要调整</h3><p>模拟暴雨影响原定徒步。建议取消当天户外活动，改为住宿休整与室内活动；住宿不变，短途交通与活动预算增加 ¥80。确认后同步更新行程和预算。</p><div class="action-row"><button class="primary" data-action="reroute">确认采用雨天方案</button><button class="outline" data-action="cancel-reroute">保留原计划</button></div></div>`:''}<div class="card"><h3>留住此刻</h3><form id="memory" class="full-form"><input name="note" aria-label="旅行笔记" placeholder="记下一处风景，或此刻的心情…" required maxlength="500"><button class="primary">＋ 打卡</button></form>${state.memories.map(x=>`<div class="log"><span>${esc(x.text)}</span><small>${esc(x.time)}</small></div>`).join('')}</div></div><div><div class="card"><h3>沿途补给 · 示例</h3>${[['便利店 / 饮水补给','示例距离 0.8 km · 营业状态待核实'],['停车场 / 公共卫生间','示例距离 1.2 km · 收费待核实'],[state.pet?'宠物医疗服务':'医疗服务','需使用真实地图确认位置和营业状态']].map(x=>`<div class="service"><strong>${x[0]}</strong><p>${x[1]}</p></div>`).join('')}</div><div class="card agent"><h3>结束今天，也收藏旅程</h3><p>记下花费与沿途片刻，归来后生成旅行档案。</p><div class="action-row"><button class="outline" data-view="wallet">记录花费</button><button class="primary" data-action="finish">结束旅行</button></div></div></div></div>`;
if(view==='wallet')html=`<div class="grid"><div class="card"><h3>旅行支出</h3><div class="facts"><div class="fact"><strong>¥${total().toFixed(2)}</strong><small>实际支出</small></div><div class="fact"><strong>¥${(state.budget-total()).toFixed(2)}</strong><small>剩余预算</small></div><div class="fact"><strong>${state.expenses.length}</strong><small>消费记录</small></div></div>${total()>state.budget?'<div class="notice">实际支出已超过预算，请调整后续安排。</div>':''}<form id="expense" class="full-form"><select name="category" aria-label="支出分类">${['交通','住宿','餐饮','活动','装备','其他'].map(x=>`<option>${x}</option>`).join('')}</select><input name="amount" type="number" step="0.01" min="0.01" max="1000000" aria-label="金额" placeholder="金额（人民币）" required><button class="primary">记一笔</button></form>${state.expenses.length?state.expenses.map((x,i)=>`<div class="log"><span>${esc(x.category)} <small>${esc(x.time)}</small></span><span>¥${x.amount.toFixed(2)} <button class="delete" aria-label="删除支出" data-delete-expense="${i}">×</button></span></div>`).join(''):'<div class="empty">还没有支出，从第一笔开始记录。</div>'}</div><div>${budget()}<div class="card agent"><h3>账本说明</h3><p>记录的是实际支出，与规划估算分开计算。本演示使用人民币单人账本，未接入支付与实时汇率。</p></div></div></div>`;
if(view==='after')html=`<div class="grid"><div class="card"><div class="section-heading"><h3>${esc(state.destination)} · 旅行手记</h3><span class="muted">${state.phase===2?'已结束':'旅行草稿'}</span></div><div class="story">${esc(story())}</div><div class="action-row"><button class="primary" data-action="export">↓ 导出完整档案</button><button class="outline" data-view="during">继续记录</button></div></div><div class="card"><h3>这一路的收获</h3><div class="facts"><div class="fact"><strong>${state.days}</strong><small>计划天数</small></div><div class="fact"><strong>${state.memories.length}</strong><small>旅行片刻</small></div><div class="fact"><strong>${state.expenses.length}</strong><small>消费记录</small></div></div><div class="budget-row"><span>实际总支出</span><strong>¥${total().toFixed(2)}</strong></div><p class="muted" style="margin-top:18px">基于当前行程和你的记录生成；没有记录的经历不会被编入游记。</p></div></div>`;
$('#content').innerHTML=html;save();}
function story(){return `这是一份${state.phase===2?'已结束行程的':'进行中的'}旅行档案。\n\n从${state.origin}出发，计划用 ${state.days} 天探索${state.destination}。${state.pet?'这次还带上了毛孩子。':''}以${state.experience}徒步为参考，给路上留出休息的时间。\n\n${state.rerouted?'途中采用了雨天替代方案，取消当天户外活动。\n\n':''}${state.memories.length?'我留下的片刻：\n'+state.memories.map(x=>`${x.time} · ${x.text}`).join('\n'):'还没有旅行笔记。到「途中陪伴」记下真实经历后，这里会自动更新。'}\n\n已记录支出 ¥${total().toFixed(2)}，预算 ¥${state.budget}。`}
function exportTrip(){const content=`# 野途旅行档案\n\n${story()}\n\n## 行程（示例，需核实）\n${Array.from({length:state.days},(_,i)=>`\n### 第 ${i+1} 天\n`+route(i+1).map(r=>`- ${r[0]} ${r[1]}：${r[2]}`).join('\n')).join('\n')}\n\n## 物资清单\n${state.checks.map(x=>`- [${x.done?'x':' '}] ${x.text}`).join('\n')}\n\n## 账本\n${state.expenses.map(x=>`- ${x.time} ${x.category} ¥${x.amount.toFixed(2)}`).join('\n')}\n\n本档案来自规则引擎演示，未接入实时天气、地图、预订与紧急服务。`;const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type:'text/markdown;charset=utf-8'}));a.href=url;a.download='野途旅行档案.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('旅行档案已导出')}
function parsePrompt(p,experience){const budget=p.match(/预算\s*(\d+)/)||p.match(/(\d+)\s*元/),days=p.match(/(\d+)\s*天/),chinese=p.match(/([一二两三四五六七八九十])天/);let destination=['莫干山','深圳','云南','黄山','杭州','北京','上海','成都','大理'].find(x=>p.includes('去'+x));if(!destination){let m=p.match(/去([^，,。\s]{2,8}?)(?:玩|旅行|徒步|[一二两三四五六七八九十\d]天|，|,|$)/);destination=m?m[1]:'莫干山'}const origin=p.match(/从([^，,。\s]{2,8}?)出发/);return {...structuredClone(initial),destination,origin:origin?origin[1]:'杭州',budget:budget?Math.max(100,Math.min(1000000,Number(budget[1]))):1500,days:Math.min(10,Math.max(1,days?Number(days[1]):chinese?{'一':1,'二':2,'两':2,'三':3,'四':4,'五':5,'六':6,'七':7,'八':8,'九':9,'十':10}[chinese[1]]:2)),pet:/带狗|携宠|带猫|宠物/.test(p),solo:!/结伴|两个人|朋友/.test(p),experience};}
$('#plan-form').onsubmit=e=>{e.preventDefault();$('#question').showModal()};$('#question').addEventListener('close',()=>{if(!['入门','熟悉','进阶'].includes($('#question').returnValue))return;const next=parsePrompt($('#prompt').value,$('#question').returnValue);next.checks=next.checks.filter(x=>next.pet||!/宠物|携宠/.test(x.text));if((state.expenses.length||state.memories.length)&&!confirm('生成新行程会替换本机当前旅行记录。需要保留时请先导出档案。继续吗？'))return;state=next;view='plan';render();toast('行程已生成：可在清单和途中陪伴中继续演示')});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){view=b.dataset.view;render()}if(b.dataset.prompt)$('#prompt').value=b.dataset.prompt;if(b.dataset.day){state.day=Number(b.dataset.day);render()}if(b.dataset.deleteCheck!==undefined){state.checks.splice(Number(b.dataset.deleteCheck),1);render()}if(b.dataset.deleteExpense!==undefined){state.expenses.splice(Number(b.dataset.deleteExpense),1);render()}const a=b.dataset.action;if(a==='start'){state.phase=1;view='during';render();toast('方案已确认。预订与实时服务仍需另行核实')}if(a==='rain'){state.pending=true;render()}if(a==='cancel-reroute'){state.pending=false;render()}if(a==='reroute'){state.pending=false;state.rerouted=true;state.day=1;render();toast('已更新当天路线，预计费用增加 ¥80')}if(a==='tired'){state.fatigued=true;toast('已调整：当日剩余活动可跳过，优先回住宿休息');state.memories.push({text:'反馈疲劳，决定缩短活动并休息。',time:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})});render()}if(a==='emergency'){const dialog=document.createElement('dialog');dialog.innerHTML='<form method="dialog"><h2>应急模式</h2><p>暂停普通行程。若有紧迫危险，请立即联系所在地紧急服务，并向可信联系人说明你的位置。</p><p style="margin-top:16px">本 demo 不提供定位、报警、医疗判断或救援派遣。请打开设备地图查看真实位置，使用手机拨号联系当地紧急服务。</p><button class="primary" style="margin-top:20px">我已了解，返回</button></form>';document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove());dialog.showModal()}if(a==='finish'){state.phase=2;view='after';render()}if(a==='export')exportTrip()});
document.addEventListener('change',e=>{if(e.target.dataset.check!==undefined){state.checks[Number(e.target.dataset.check)].done=e.target.checked;render()}});
document.addEventListener('submit',e=>{if(!['add-item','expense','memory'].includes(e.target.id))return;e.preventDefault();const data=new FormData(e.target),time=new Date().toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});if(e.target.id==='add-item'){const text=String(data.get('item')).trim();if(!text)return;state.checks.push({text,done:false})}if(e.target.id==='expense'){const amount=Number(data.get('amount'));if(!Number.isFinite(amount)||amount<=0||amount>1000000)return;state.expenses.push({amount,category:data.get('category'),time})}if(e.target.id==='memory'){const text=String(data.get('note')).trim();if(!text)return;state.memories.push({text,time})}render();toast('已保存到当前浏览器')});$('#export').onclick=exportTrip;render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_trip_summary',description:'读取当前演示旅行的行程摘要和实际支出，不修改数据',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected empty object');return {destination:state.destination,days:state.days,budget:state.budget,spent:total(),phase:state.phase,rerouted:state.rerouted}}})).catch(()=>{})}catch{}}

